/**
 * Normalizes subject alias and retrieves questions for specified class, subject, and mode.
 * @param {string|number} classNumber - 1 to 5
 * @param {string} subject - 'english' | 'mathematics' | 'evs' | 'hindi' | 'kannada' (or aliases 'science', 'gk', 'maths')
 * @param {'image'|'text'} mode - 'image' or 'text'
 * @returns {Array} List of 10 questions for that mode
 */
export function getTrainingQuestions(classNumber, subject, mode = 'image') {
    if (!classNumber || !subject) return [];
    
    const normClass = String(classNumber);
    const normSubject = String(subject).toLowerCase().trim();
    
    const aliasMap = {
        'science': 'evs',
        'gk': 'evs',
        'general knowledge': 'evs',
        'maths': 'mathematics',
        'math': 'mathematics'
    };
    
    const resolvedSubject = aliasMap[normSubject] || normSubject;
    const key = `${normClass}-${resolvedSubject}`;
    
    const moduleEntry = trainingData[key];
    if (!moduleEntry) {
        console.warn(`No training questions registered for key: ${key}`);
        return [];
    }
    
    if (mode === 'text') {
        return moduleEntry.textQuestions || [];
    }
    if (mode === 'all') {
        return [...(moduleEntry.imageQuestions || []), ...(moduleEntry.textQuestions || [])];
    }
    return moduleEntry.imageQuestions || [];
}

/**
 * Returns available training counts and metadata for a given class and subject,
 * or overall system summary if called without arguments.
 */
export function getTrainingSummary(classNumber, subject) {
    if (!classNumber && !subject) {
        let totalQuestions = 0;
        let totalImageQuestions = 0;
        let totalTextQuestions = 0;
        const keys = Object.keys(trainingData);
        for (const k of keys) {
            totalImageQuestions += (trainingData[k].imageQuestions || []).length;
            totalTextQuestions += (trainingData[k].textQuestions || []).length;
        }
        totalQuestions = totalImageQuestions + totalTextQuestions;
        return {
            totalModules: keys.length,
            totalQuestions,
            totalImageQuestions,
            totalTextQuestions
        };
    }

    const normClass = String(classNumber);
    const normSubject = String(subject).toLowerCase().trim();
    const aliasMap = {
        'science': 'evs',
        'gk': 'evs',
        'maths': 'mathematics'
    };
    const resolvedSubject = aliasMap[normSubject] || normSubject;
    const key = `${normClass}-${resolvedSubject}`;
    const moduleEntry = trainingData[key] || { imageQuestions: [], textQuestions: [] };
    
    return {
        key,
        classNumber: normClass,
        subject: resolvedSubject,
        imageCount: (moduleEntry.imageQuestions || []).length,
        textCount: (moduleEntry.textQuestions || []).length,
        totalCount: (moduleEntry.imageQuestions || []).length + (moduleEntry.textQuestions || []).length
    };
}
